def snapshot_layers(layers):
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")
    result = {}
    for layer in layers:
        if not isinstance(layer, dict):
            raise TypeError("each layer must be a dict")
        if "name" not in layer or "settings" not in layer:
            raise ValueError("missing required data")
        name = layer["name"]
        settings = layer["settings"]
        if not isinstance(name, str) or not name or not isinstance(settings, dict):
            raise ValueError("malformed layer")
        if name in result:
            raise ValueError("duplicate layer")
        result[name] = settings.copy()
    return result

